import{_ as e,o as s,c as n,a2 as o}from"./chunks/framework.CQdiwDJy.js";const u=JSON.parse('{"title":"架构总览","description":"","frontmatter":{},"headers":[],"relativePath":"reference/architecture.md","filePath":"reference/architecture.md","lastUpdated":1788601681000}'),c={name:"reference/architecture.md"};function t(p,a,i,l,r,d){return s(),n("div",null,[...a[0]||(a[0]=[o(`<h1 id="架构总览" tabindex="-1">架构总览 <a class="header-anchor" href="#架构总览" aria-label="Permalink to &quot;架构总览&quot;">​</a></h1><p>Tau 是一个 pnpm workspace monorepo：<code>packages/</code> 是能力层，<code>app/</code> 是界面层，全部 TypeScript ESM。核心原则是<strong>依赖单向</strong>——界面层依赖能力层，能力层互相之间只依赖更底层。</p><h2 id="包结构" tabindex="-1">包结构 <a class="header-anchor" href="#包结构" aria-label="Permalink to &quot;包结构&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>packages/</span></span>
<span class="line"><span>  core/      类型、配置、工具注册表契约（ToolDefinition / ToolResult）</span></span>
<span class="line"><span>  tools/     确定性工具层：file/sys/net/text 四族内置工具</span></span>
<span class="line"><span>  engine/    执行与安全：reviewPlan() 确定性审查 + runPlan() 唯一执行通道</span></span>
<span class="line"><span>  ai/        provider 抽象：AIProvider 接口 + 七家实现 + 流式 wire 层</span></span>
<span class="line"><span>  skills/    技能运行时 + 随 CLI 发布的内置技能（产品内容）</span></span>
<span class="line"><span>  plugins/   MCP 客户端层（插件工具一律 medium risk）</span></span>
<span class="line"><span>  agent/     编排：ask/goal 共用的目录装配与规划管线</span></span>
<span class="line"><span>  ui/ markdown/  终端渲染原语 / 双形态 markdown（HTML + ANSI）</span></span>
<span class="line"><span>app/</span></span>
<span class="line"><span>  cli/ tui/ webui/   三种界面，同一引擎同一道门</span></span></code></pre></div><h2 id="核心管线" tabindex="-1">核心管线 <a class="header-anchor" href="#核心管线" aria-label="Permalink to &quot;核心管线&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>意图 → provider.plan() → validatePlanResponse()（zod 严格 JSON）</span></span>
<span class="line"><span>     → reviewPlan()（确定性安全审查）→ 用户确认 → runPlan()（唯一执行通道）</span></span></code></pre></div><p>三个不变量：(1) AI 永不自我评分——审查是确定性代码；(2) <code>runPlan()</code> 是唯一执行通道，不存在旁路；(3) 计划是严格 JSON，宽松输出会被校验拒绝。</p><h2 id="流式层-v0-5-0" tabindex="-1">流式层（v0.5.0） <a class="header-anchor" href="#流式层-v0-5-0" aria-label="Permalink to &quot;流式层（v0.5.0）&quot;">​</a></h2><p><code>packages/ai/src/chat-stream.ts</code> 是统一流式 wire 层：四种 wire 协议（OpenAI SSE、Anthropic Messages SSE、Gemini <code>alt=sse</code>、Ollama NDJSON）被折叠成 provider 无关的 <code>ProviderStreamEvent</code>（<code>reasoning_delta</code> / <code>text_delta</code> / <code>usage</code>）。agent 层（<code>planIntentStream</code> / <code>runGoal</code> 的 <code>onPlanStream</code>）与 WebUI（<code>/api/plan/stream</code>、思考面板）直接消费同一种事件形状，层层透传、不再转换。</p><h2 id="目录治理" tabindex="-1">目录治理 <a class="header-anchor" href="#目录治理" aria-label="Permalink to &quot;目录治理&quot;">​</a></h2><p>仓库对&quot;什么放哪里&quot;有规范性约束（见 <code>AGENTS/architecture.md</code> 的 directory governance 表）：AI 行为文档在根部 <code>AGENTS*</code>；跨切面的开发技能在 <code>.claude/skills/</code>；单包技能挨着它治理的代码；随 CLI 发布的技能是产品内容（运行时数据），在 <code>packages/skills/bundled/</code>；文档站即仓库根的 <code>docs/</code> 目录（工作区 <code>@tau/docs</code>，私有）。</p>`,11)])])}const m=e(c,[["render",t]]);export{u as __pageData,m as default};
